const normalizarStatus = v =>
  v === null || v === undefined ? ''
  : String(v).normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase().trim();

const map = {
  'CPF (A)': 'CPF',
  'NOME ALUNO (B)': 'NOME_ALUNO',
  'NOME ESCOLA (C)': 'NOME_ESCOLA',
  'CPF (D)': 'CPF',
  'VAZIA (E)': '',
  'VAZIA (F)': '',
  'VAZIA (G)': '',
  'VAZIA (H)': '',
  'VAZIA (I)': '',
  'VAZIA (J)': '',
  'TELEFONE (K)': 'TELEFONE',
  'VAZIA (L)': '',
  'VAZIA (M)': '',
  'MENSALIDADE (N)': '',
  'DATA RECEBIVEL RECENTE (O)': 'DATA_RECEBIVEL_VENCIDO_MAIS_RECENTE',
  'VALOR DEVIDO (P)': 'VALOR_DEVIDO',
  'EMAIL (Q)': 'EMAIL',
  'NOME RESPONSAVEL (R)': 'NOME_RESPONSAVEL',
  'CPF (S)': 'CPF',
  'VAZIA (T)': '',
  'VAZIA (U)': '',
  'VAZIA (V)': '',
  'VAZIA (W)': '',
  'VAZIA (X)': '',
  'VAZIA (Y)': '',
  'TELEFONE (Z)': 'TELEFONE',
  'VAZIA (AA)': '',
  'EMAIL (AB)': 'EMAIL'
};

const limparBase = v => v === null || v === undefined ? '' : String(v).replace(/["']/g, '').trim();
const formatarCPF = v => '="' + String(v ?? '').replace(/\D/g, '').padStart(11, '0').slice(-11) + '"';
const formatarTelefone = v => limparBase(v).replace(/\D/g, '');
const formatarEmail = v => limparBase(v).toLowerCase();

const serialParaData = v => {
  const s = parseInt(String(v).trim());
  if (isNaN(s) || s < 1) return '';
  const d = new Date((s - 25569) * 86400000);
  return d.getUTCFullYear() +
    String(d.getUTCMonth() + 1).padStart(2, '0') +
    String(d.getUTCDate()).padStart(2, '0');
};

const formatarData = v => {
  if (!v) return '';
  const s = limparBase(v);
  if (!s) return '';
  if (/^\d{8}$/.test(s)) return s;
  if (/^\d{1,2}\/\d{1,2}\/\d{4}$/.test(s)) {
    const [dia, mes, ano] = s.split('/');
    return ano + mes.padStart(2, '0') + dia.padStart(2, '0');
  }
  if (/^\d{4,6}$/.test(s)) return serialParaData(s);
  return '';
};

const formatarValor = v => {
  if (v === null || v === undefined || v === '') return '="0,00"';
  const s = String(v).trim().replace(/[^\d.,]/g, '');
  let num;
  if (/^\d{1,3}(\.\d{3})*,\d+$/.test(s)) {
    num = parseFloat(s.replace(/\./g, '').replace(',', '.'));
  } else if (/^\d+\.\d+$/.test(s)) {
    num = parseFloat(s);
  } else {
    num = parseFloat(s.replace(',', '.'));
  }
  if (isNaN(num)) return '="0,00"';
  return '="' + num.toFixed(2).replace('.', ',') + '"';
};

let inputData = $input.all().map(i => i.json);
if (inputData.length === 1 && Array.isArray(inputData[0].data)) inputData = inputData[0].data;

inputData = inputData.filter(row => {
  const chaveStatus = Object.keys(row).find(k => normalizarStatus(k) === 'status');
  if (!chaveStatus) return false;
  return normalizarStatus(row[chaveStatus]) === 'inadimplente';
});

const output = inputData.map(row => {
  const novo = {};
  for (const [saida, entrada] of Object.entries(map)) {
    let valor = entrada ? row[entrada] ?? '' : '';
    switch (saida) {
      case 'CPF (A)': case 'CPF (D)': case 'CPF (S)':
        valor = formatarCPF(valor); break;
      case 'TELEFONE (K)': case 'TELEFONE (Z)':
        valor = formatarTelefone(valor); break;
      case 'EMAIL (Q)': case 'EMAIL (AB)':
        valor = formatarEmail(valor); break;
      case 'DATA RECEBIVEL RECENTE (O)':
        valor = formatarData(valor); break;
      case 'VALOR DEVIDO (P)':
        valor = formatarValor(valor); break;
      case 'MENSALIDADE (N)':
        valor = 'MENSALIDADE'; break;
      default:
        valor = limparBase(valor);
    }
    novo[saida] = String(valor);
  }
  return { json: novo };
});

return output.filter(item => Object.values(item.json).some(v => v !== ''));

const binaryData = await this.helpers.getBinaryDataBuffer(0, 'file0');
const raw = binaryData.toString('utf-8');

const lines = raw.split('\r\n');
const delimiter = lines[0].includes(';') ? ';' : ',';
const output = [];

for (const line of lines) {
  if (!line.trim()) continue;

  let l = line;

  if (l.startsWith('"') && l.endsWith('"')) {
    l = l.slice(1, -1);
  }

  l = l.replace(/""/g, '\x01');

  let parts = l.split(delimiter);
  parts = parts.slice(0, 13);

  const cleaned = parts.map(cell => {
    cell = cell.replace(/\x01/g, '').trim();
    cell = cell.replace(/^(\d+),(\d+)$/, '$1.$2');
    cell = cell.replace(/,/g, ' | ');
    cell = cell.replace(/"/g, '');
    return cell;
  });

  if (delimiter === ',' && cleaned.length === 13 &&
      /^\d+$/.test(cleaned[5]) && /^\d{1,2}$/.test(cleaned[6])) {
    cleaned[5] = cleaned[5] + '.' + cleaned[6];
    cleaned.splice(6, 1);
    cleaned.push('');
  }

  output.push(cleaned.join(','));
}

const newCsv = output.join('\r\n');
const newBinary = await this.helpers.prepareBinaryData(
  Buffer.from(newCsv, 'utf-8'),
  'cleaned.csv',
  'text/csv'
);

return [{ json: {}, binary: { file0: newBinary } }];
